/* ══════════════════════════════════════════════════════════════════════
   DYNAMIC ANIMATED TAB FAVICON ENGINE
   Forces Chrome/Firefox/Safari/Edge to animate the browser tab favicon in real time
  ══════════════════════════════════════════════════════════════════════ */
(function() {
  const FAVICON_FRAMES = ["data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,"];
  let frameIdx = 0;
  let linkEl = null;

  function initFaviconAnimation() {
    linkEl = document.querySelector('link[rel="icon"]') || document.querySelector('link[rel="shortcut icon"]');
    if (!linkEl) {
      linkEl = document.createElement("link");
      linkEl.rel = "icon";
      document.head.appendChild(linkEl);
    }
    linkEl.type = "image/png";

    function step() {
      if (linkEl) {
        linkEl.href = FAVICON_FRAMES[frameIdx];
      }
      frameIdx = (frameIdx + 1) % FAVICON_FRAMES.length;
    }

    step();
    setInterval(step, 70);
  }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", initFaviconAnimation);
  } else {
    initFaviconAnimation();
  }
})();
